/*
A = T ⊗ P
                    where 
                    T: ℝ ^ (a×b): a sequence
                    P: ℝ ^ (c×d): a sequence
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    MatrixD A;

    heartlib(
        const Eigen::MatrixXd & T,
        const Eigen::MatrixXd & P)
    {
        const long a = T.rows();
        const long b = T.cols();
        const long c = P.rows();
        const long d = P.cols();
        assert( T.rows() == a );
        assert( P.rows() == c );
        // A = T ⊗ P
        MatrixD kron(a*c, b*d);
        for( int i=0; i<a; i++){
            for( int j=0; j<b; j++){
                kron.block(i*c,j*d,c,d) = (T)(i, j)*(P);
            }
        }
        A = kron;
    }
};

