function output = heartlib(T, P)
% output = heartlib(T, P)
%
%    A = T ⊗ P
%                        where 
%                        T: ℝ ^ (a×b): a sequence
%                        P: ℝ ^ (c×d): a sequence
    a = size(T, 1);
    b = size(T, 2);
    c = size(P, 1);
    d = size(P, 2);
    assert( isequal(size(T), [a, b]) );
    assert( isequal(size(P), [c, d]) );

    % A = T ⊗ P

    A = kron(T, P);
    output.A = A;
end

